def _stage_shape(inputs, targets, mb, hidden_size):
    """[microbatch, seq_len, hidden_size] shape of the inter-stage tensors."""
    ref = None
    for source in (inputs, targets):
        try:
            cand = source[mb]
        except (TypeError, IndexError, KeyError):
            cand = None
        if torch.is_tensor(cand) and cand.dim() >= 2:
            ref = cand
            break
    if ref is None:
        raise ValueError("cannot infer the inter-stage tensor shape from inputs/targets")
    if ref.dim() >= 3:
        return (ref.shape[0], ref.shape[1], ref.shape[2])
    return (ref.shape[0], ref.shape[1], hidden_size)


